            "ATION_SCHEMA.COLUMNS where TABLE_NAME=@TargetTable)\r\n                           " +
            "     begin\r\n                                    Exec( N\'Alter TABLE \'+@TargetTab" +
            "le+\' ADD [\' +@ColumnName + \'_MAX] real NULL \')\r\n                                " +
