            "E @NewColName in (select COLUMN_NAME from INFORMATION_SCHEMA.COLUMNS where TABLE" +
            "_NAME=@TargetTable)\r\n                                            BEGIN\r\n        " +
            "                                        set @i+=1 \r\n                            " +
            "                    set @NewColName = @ColumnName + \'_MAX\' + convert(nvarchar,@i" +
