            "TargetTable)\r\n                                begin\r\n                           " +
            "         Exec( N\'Alter TABLE \'+@TargetTable+\' ADD [\' +@ColumnName + \'_AVG] real " +
            "NULL \')\r\n                                end\r\n                            else\r\n" +
            "                                begin\r\n                                    selec" +
            "t @DataType=[DATA_TYPE]  from INFORMATION_SCHEMA.COLUMNS where TABLE_NAME=@Targe" +
            "tTable and COLUMN_NAME=@TempColName\r\n                                    if @Dat" +
            "aType not in (\'real\')\r\n                                        begin\r\n          " +
            "                                  set @i = 1\r\n                                  " +
            "          set @NewColName = @ColumnName + \'_AVG\' + convert(nvarchar,@i)\r\n       " +
            "                                     WHILE @NewColName in (select COLUMN_NAME fr" +
            "om INFORMATION_SCHEMA.COLUMNS where TABLE_NAME=@TargetTable)\r\n                  " +
