        [global::System.Configuration.DefaultSettingValueAttribute("CREATE FUNCTION [dbo].[Udf_SplitString] \r\n(\r\n      @InputString  VARCHAR(max),\r\n " +
            "     @Delimiter    VARCHAR(50)\r\n)\r\n\r\nRETURNS @Items TABLE \r\n(\r\n      Item    VAR" +
            "CHAR(8000)\r\n)\r\n\r\nAS\r\nBEGIN\r\n      IF @Delimiter = \' \'\r\n      BEGIN\r\n            " +
            "SET @Delimiter = \',\'\r\n            SET @InputString = REPLACE(@InputString, \' \', " +
            "@Delimiter)\r\n      END\r\n\r\n      IF (@Delimiter IS NULL OR @Delimiter = \'\')\r\n    " +
            "        SET @Delimiter = \',\'\r\n\r\n--INSERT INTO @Items VALUES (@Delimiter) -- Diag" +
            "nostic\r\n--INSERT INTO @Items VALUES (@InputString) -- Diagnostic\r\n\r\n      DECLAR" +
            "E @Item           VARCHAR(8000)\r\n      DECLARE @ItemList       VARCHAR(max)\r\n   " +
            "   DECLARE @DelimIndex     INT\r\n\r\n      SET @ItemList = @InputString\r\n      SET " +
            "@DelimIndex = CHARINDEX(@Delimiter, @ItemList, 0)\r\n      WHILE (@DelimIndex != 0" +
            ")\r\n      BEGIN\r\n            SET @Item = SUBSTRING(@ItemList, 0, @DelimIndex)\r\n  " +
            "          INSERT INTO @Items VALUES (@Item)\r\n\r\n            -- Set @ItemList = @I" +
            "temList minus one less item\r\n            SET @ItemList = SUBSTRING(@ItemList, @D" +
            "elimIndex+1, LEN(@ItemList)-@DelimIndex)\r\n            SET @DelimIndex = CHARINDE" +
            "X(@Delimiter, @ItemList, 0)\r\n      END -- End WHILE\r\n\r\n      IF @Item IS NOT NUL" +
            "L -- At least one delimiter was encountered in @InputString\r\n      BEGIN\r\n      " +
            "      SET @Item = @ItemList\r\n            INSERT INTO @Items VALUES (@Item)\r\n    " +
            "  END\r\n\r\n      -- No delimiters were encountered in @InputString, so just return" +
            " @InputString\r\n      ELSE INSERT INTO @Items VALUES (@InputString)\r\n\r\n      RETU" +
            "RN\r\n\r\nEND -- End Function")]
